begin;
select '1..3' as tap;
create function pg_temp.require(ok boolean) returns void language plpgsql as $$begin perform set_config('p11.assert', (coalesce(nullif(current_setting('p11.assert',true),''),'0')::int+1)::text,true);if ok is distinct from true then raise exception 'Comment assertion failed %',current_setting('p11.assert');end if;end$$;
create function pg_temp.rejects(command text,code text) returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'Expected comment rejection %',code;end$$;
grant execute on function pg_temp.require(boolean),pg_temp.rejects(text,text) to authenticated;
grant execute on function pg_temp.rejects(text,text) to anon;
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333331',true);
select set_config('p11.id',public.add_comment('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8','<script>window.p11=true</script> javascript:alert(1)',array['33333333-3333-4333-8333-333333333332']::uuid[],false,'11000000-0000-4000-8000-000000000001')->>'commentId',true);
select pg_temp.require(public.add_comment('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8','<script>window.p11=true</script> javascript:alert(1)',array['33333333-3333-4333-8333-333333333332']::uuid[],false,'11000000-0000-4000-8000-000000000001')->>'commentId'=current_setting('p11.id'));
select pg_temp.require(public.read_comment_history(current_setting('p11.id')::uuid)->0->>'body'='<script>window.p11=true</script> javascript:alert(1)');
select pg_temp.rejects($q$select public.add_comment('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8','changed','{}',false,'11000000-0000-4000-8000-000000000001')$q$,'22023');
select pg_temp.rejects($q$update public.comment_revisions set body='overwrite' where comment_id=current_setting('p11.id')::uuid$q$,'42501');
select pg_temp.rejects($q$select public.revise_comment(current_setting('p11.id')::uuid,'stale','{}','edit','Reason',0,gen_random_uuid())$q$,'40001');
select 'ok 1 - P11_A1: SQL preserves literal unsafe text; exact retries, immutable originals and stale-version rejection (execution checked in UI/browser)' as tap;
select set_config('p11.draft',public.add_comment('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8','PRIVATE DRAFT','{}',true,gen_random_uuid())->>'commentId',true);
select set_config('p11.published',public.add_comment('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8','PRIVATE EARLIER DRAFT','{}',true,gen_random_uuid())->>'commentId',true);
select public.revise_comment(current_setting('p11.published')::uuid,'Published final text','{}','publish','Ready to share',1,gen_random_uuid());
select pg_temp.rejects($q$select public.add_comment('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8',repeat('x',8001),'{}',false,gen_random_uuid())$q$,'22023');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333332',true);
select pg_temp.require(jsonb_array_length(public.mention_candidates('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8'))=2);
select pg_temp.require(public.read_comment_history(current_setting('p11.draft')::uuid)='[]');
select pg_temp.require(jsonb_array_length(public.read_comment_history(current_setting('p11.published')::uuid))=1);
select pg_temp.require((select count(*)=1 from public.comment_revisions where comment_id=current_setting('p11.published')::uuid));
select pg_temp.require((select count(*)=0 from public.comments where id=current_setting('p11.draft')::uuid));
select pg_temp.rejects($q$select public.revise_comment(current_setting('p11.id')::uuid,'rewrite','{}','edit','Reason',1,gen_random_uuid())$q$,'42501');
select pg_temp.rejects($q$select public.add_comment('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8','Mention outsider',array['33333333-3333-4333-8333-333333333333']::uuid[],false,gen_random_uuid())$q$,'42501');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select pg_temp.require(public.read_comments('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8') is null);
select pg_temp.require((select count(*)=0 from public.comment_evidence));
select pg_temp.require(public.read_comment_history(current_setting('p11.id')::uuid)='[]');
select pg_temp.require(public.mention_candidates('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8')='[]');
select pg_temp.require((select count(*)=0 from public.comments));
select pg_temp.require((select count(*)=0 from public.comment_revisions));
select pg_temp.require((select count(*)=0 from public.comment_evidence));
select pg_temp.rejects($q$select public.add_comment('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8','Unauthorized','{}',false,gen_random_uuid())$q$,'42501');
reset role;
select pg_temp.require((select count(*)=1 from public.outbox_jobs where event_type='comment_mentions'));
select pg_temp.require(not exists(select 1 from public.outbox_jobs where payload::text like '%script%' or payload::text like '%PRIVATE%'));
update public.record_grants set expires_at=statement_timestamp()-interval'1 second',starts_at=statement_timestamp()-interval'2 days' where work_item_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8';
update public.role_assignments set status='revoked' where term_membership_id='66666666-6666-4666-8666-666666666662' and role_id='55555555-5555-4555-8555-555555555559';
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333332',true);
select pg_temp.require(public.mention_candidates('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8')='[]');
select pg_temp.require(public.read_comments('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8') is null);
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333331',true);
select pg_temp.require(jsonb_array_length(public.mention_candidates('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8'))=1);
select pg_temp.rejects($q$select public.add_comment('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8','Expired mention',array['33333333-3333-4333-8333-333333333332']::uuid[],false,gen_random_uuid())$q$,'42501');
select 'ok 2 - P11_A2: unrelated and expired subjects cannot enumerate comments/revisions/candidates; private drafts, writes, mentions and redacted outbox enforced' as tap;
reset role;
-- A real FK to the existing immutable decision-bearing revision, not a made-up decision API.
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333331',true);
insert into public.deliverable_revisions(work_item_id,work_version,criteria_revision,workflow_state,title,outcome,acceptance_criteria,owner_member_id,reason,review_evidence,actor_id)
values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8',900,1,'accepted','Fictional evidence test','Fictional output','Criteria','33333333-3333-4333-8333-333333333331','Synthetic trusted historical decision','comment:'||current_setting('p11.id')||':1','33333333-3333-4333-8333-333333333331');
select pg_temp.rejects($q$insert into public.deliverable_revisions(work_item_id,work_version,criteria_revision,workflow_state,title,outcome,acceptance_criteria,owner_member_id,reason,review_evidence,actor_id)
values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8',901,1,'accepted','Fixture','Output','Criteria','33333333-3333-4333-8333-333333333331','Invalid draft evidence','comment:'||current_setting('p11.draft')||':1','33333333-3333-4333-8333-333333333331')$q$,'42501');
set local role authenticated;
select public.revise_comment(current_setting('p11.id')::uuid,'Later amendment','{}','edit','Clarification after decision',1,'11000000-0000-4000-8000-000000000002');
select pg_temp.require(public.read_comment_history(current_setting('p11.id')::uuid)->0->>'body'='<script>window.p11=true</script> javascript:alert(1)');
select pg_temp.require(public.read_comment_history(current_setting('p11.id')::uuid)->1->>'body'='Later amendment');
select pg_temp.require((select count(*)=1 from public.comment_evidence where comment_id=current_setting('p11.id')::uuid and revision=1 and purpose='decision'));
select pg_temp.require((select value->'evidence'->0->>'revision'='1' from jsonb_array_elements(public.read_comments('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8')->'items') where value->>'id'=current_setting('p11.id')));
select pg_temp.rejects($q$select public.revise_comment(current_setting('p11.id')::uuid,'','{}','remove','Delete decision evidence',2,gen_random_uuid())$q$,'55000');
select public.revise_comment(current_setting('p11.id')::uuid,'','{}','redact','Sensitive text correction',2,gen_random_uuid());
select pg_temp.require(public.read_comment_history(current_setting('p11.id')::uuid)->0->'body'='null'::jsonb);
select pg_temp.require((select count(*)=0 from public.comment_revisions where comment_id=current_setting('p11.id')::uuid));
select pg_temp.require((select value->'body'='null'::jsonb from jsonb_array_elements(public.read_comments('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8')->'items') where value->>'id'=current_setting('p11.id')));
select public.revise_comment(current_setting('p11.draft')::uuid,'','{}','remove','No longer needed',1,gen_random_uuid());
reset role;
select pg_temp.require((select body='<script>window.p11=true</script> javascript:alert(1)' from public.comment_revisions where comment_id=current_setting('p11.id')::uuid and revision=1));
select pg_temp.require((select count(*)=1 from public.comment_evidence where comment_id=current_setting('p11.id')::uuid));
set local role anon;
select pg_temp.rejects($q$select public.read_comments('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa8')$q$,'42501');
select pg_temp.rejects($q$select * from public.comment_revisions$q$,'42501');
reset role;
select 'ok 3 - P11_A3: decision FK pins original revision; amendment and reason are retained, referenced deletion blocked, reasoned redaction withholds bodies without erasing evidence' as tap;
rollback;
